        if([configuration[@"edgeSweep"] boolValue]){center=[slider coordinateWithNormalizedOffset:CGVectorMake(18.5/300,.5)];[self edgeSweep:center];}else if(configuration[@"contacts"])[self contacts:configuration[@"contacts"] at:center];else if([configuration[@"tap"] boolValue])[center tap];else[center pressForDuration:[configuration[@"hold"] doubleValue]];
